using StartPos.Core.Tables;
using static StartPos.Core.Tables.StartPosTableNames;

namespace StartPos.Core.Compare;

/// <summary>
/// How rows of a start_pos table are matched between two packs. Some IDs are arbitrary
/// (generated by whoever wrote the table, and not kept in a built startpos), so rows are matched
/// on <see cref="Match"/>, <see cref="Ignore"/>d columns are not compared, and
/// <see cref="Translate"/>d columns are compared through what they point at.
/// </summary>
public sealed record TableMatchSpec(
    string Table,
    string[] Match,
    string[]? Ignore = null,
    (string Column, string Table, string IdColumn, string KeyColumn)[]? Translate = null);

public static class StartPosMatchSpecs
{
    public static readonly IReadOnlyDictionary<string, TableMatchSpec> All = new[]
    {
        new TableMatchSpec(Calendars, ["campaign"]),
        new TableMatchSpec(CharacterAncillaries, ["character_id", "ancillary"], ["id"]),
        new TableMatchSpec(CharacterToSettlements, ["character"],
            Translate: [("settlement", Settlements, "id", "settlement_id")]),
        new TableMatchSpec(CharacterTraits, ["character_id", "trait_level"], ["id"]),
        new TableMatchSpec(Characters, ["ID"]),
        new TableMatchSpec(Diplomacy, ["faction1", "faction2"], ["key"]),
        new TableMatchSpec(EntityAssociationFactionRegions, ["faction", "region", "tag"]),
        new TableMatchSpec(Factions, ["faction"]),
        new TableMatchSpec(HordeDetails, ["general"]),
        new TableMatchSpec(LandUnits, ["general", "unit_type"], ["id"]),
        new TableMatchSpec(PastEvents, ["event", "source", "target", "turns_ago"]),
        new TableMatchSpec(RegionForeignSlots, ["faction", "region", "slot_set"]),
        new TableMatchSpec(RegionSlotTemplates, ["region", "slot_template", "slot_type"], ["id"]),
        new TableMatchSpec(Regions, ["region"]),
        new TableMatchSpec(Settlements, ["settlement_id"], ["id"]),
        new TableMatchSpec(StartingGeneralOptions, ["general", "frontend_faction_leader"], ["id"]),
        new TableMatchSpec(Technologies, ["faction", "technology"]),
        new TableMatchSpec(VictoryConditions, ["start_pos_faction", "region", "victory_type"]),
    }.ToDictionary(s => s.Table, StringComparer.Ordinal);
}

/// <summary>The differences between one table in two table sets ("left" and "right").</summary>
public sealed class TableDiffResult(string table)
{
    public string Table { get; } = table;
    public int LeftRows { get; set; }
    public int RightRows { get; set; }
    public int Matched { get; set; }
    public List<DbRow> OnlyLeft { get; } = [];
    public List<DbRow> OnlyRight { get; } = [];

    /// <summary>
    /// Left's rows that right does not have as they are: unmatched rows and matched rows with a
    /// differing column. These are the rows as the table holds them (links not translated).
    /// </summary>
    public List<DbRow> LeftDiffering { get; } = [];

    /// <summary>The same for right.</summary>
    public List<DbRow> RightDiffering { get; } = [];

    /// <summary>Column → (matched rows where it differs, examples).</summary>
    public SortedDictionary<string, (int Count, List<string> Examples)> ColumnMismatches { get; } = new(StringComparer.Ordinal);

    public bool Identical => OnlyLeft.Count == 0 && OnlyRight.Count == 0 && ColumnMismatches.Count == 0;
}

public static class TableDiff
{
    /// <summary>
    /// Compares every table in either set that has a match spec. <paramref name="ignoreColumns"/>
    /// are left out of matching and comparing in every table (e.g. "campaign", to compare two
    /// campaigns' startpos files).
    /// </summary>
    public static List<TableDiffResult> Compare(StartPosTables left, StartPosTables right, int maxExamples = 5,
        IReadOnlyCollection<string>? ignoreColumns = null)
    {
        var names = left.All.Select(t => t.Name).Union(right.All.Select(t => t.Name)).Order(StringComparer.Ordinal);
        var results = new List<TableDiffResult>();
        foreach (string name in names)
        {
            if (!StartPosMatchSpecs.All.TryGetValue(name, out var spec))
                continue;
            results.Add(Compare(spec, left, right, maxExamples, ignoreColumns));
        }
        return results;
    }

    public static TableDiffResult Compare(TableMatchSpec spec, StartPosTables left, StartPosTables right, int maxExamples = 5,
        IReadOnlyCollection<string>? ignoreColumns = null)
    {
        var result = new TableDiffResult(spec.Table);
        var ignore = new HashSet<string>(spec.Ignore ?? [], StringComparer.Ordinal);
        ignore.UnionWith(ignoreColumns ?? []);
        string[] match = spec.Match.Where(c => !ignore.Contains(c)).ToArray();
        var leftRows = Normalise(spec, left);
        var rightRows = Normalise(spec, right);
        result.LeftRows = leftRows.Count;
        result.RightRows = rightRows.Count;

        string MatchKey(Row r) => string.Join(" | ", match.Select(r.Compared.Str));
        string RowText(Row r) => string.Join("", r.Compared.Where(p => !ignore.Contains(p.Key)).OrderBy(p => p.Key, StringComparer.Ordinal)
            .Select(p => DbValue.ToText(p.Value)));

        var rightGroups = rightRows.GroupBy(MatchKey).ToDictionary(g => g.Key, g => g.ToList(), StringComparer.Ordinal);
        foreach (var group in leftRows.GroupBy(MatchKey))
        {
            var lefts = group.OrderBy(RowText, StringComparer.Ordinal).ToList();
            var rights = rightGroups.Remove(group.Key, out var list) ? list.OrderBy(RowText, StringComparer.Ordinal).ToList() : [];
            int pairs = Math.Min(lefts.Count, rights.Count);
            for (int i = 0; i < pairs; i++)
            {
                result.Matched++;
                bool differs = false;
                foreach (string column in lefts[i].Compared.Keys.Union(rights[i].Compared.Keys))
                {
                    if (ignore.Contains(column))
                        continue;
                    string a = lefts[i].Compared.Str(column), b = rights[i].Compared.Str(column);
                    if (a == b)
                        continue;
                    differs = true;
                    var (count, examples) = result.ColumnMismatches.GetValueOrDefault(column, (0, []));
                    if (examples.Count < maxExamples)
                        examples.Add($"{group.Key}: {Show(a)} vs {Show(b)}");
                    result.ColumnMismatches[column] = (count + 1, examples);
                }
                if (differs)
                {
                    result.LeftDiffering.Add(lefts[i].Original);
                    result.RightDiffering.Add(rights[i].Original);
                }
            }
            foreach (var row in lefts.Skip(pairs))
            {
                result.OnlyLeft.Add(row.Compared);
                result.LeftDiffering.Add(row.Original);
            }
            foreach (var row in rights.Skip(pairs))
            {
                result.OnlyRight.Add(row.Compared);
                result.RightDiffering.Add(row.Original);
            }
        }
        foreach (var row in rightGroups.Values.SelectMany(g => g))
        {
            result.OnlyRight.Add(row.Compared);
            result.RightDiffering.Add(row.Original);
        }
        return result;
    }

    /// <summary>A row as the table holds it, and as it is compared (links translated).</summary>
    private sealed record Row(DbRow Original, DbRow Compared);

    /// <summary>The table's rows, each with a copy where translated columns are replaced by the key they point at.</summary>
    private static List<Row> Normalise(TableMatchSpec spec, StartPosTables tables)
    {
        var rows = tables.Find(spec.Table)?.Rows ?? [];
        if (spec.Translate is not { Length: > 0 })
            return rows.Select(r => new Row(r, r)).ToList();
        var lookups = spec.Translate.ToDictionary(t => t.Column, t =>
            (tables.Find(t.Table)?.Rows ?? []).GroupBy(r => r.Str(t.IdColumn)).ToDictionary(g => g.Key, g => g.First().Str(t.KeyColumn)));
        return rows.Select(r =>
        {
            var copy = new DbRow(r);
            foreach (var (column, lookup) in lookups)
                copy[column] = lookup.TryGetValue(r.Str(column), out var key) ? key : "?" + r.Str(column);
            return new Row(r, copy);
        }).ToList();
    }

    private static string Show(string s) => s.Length == 0 ? "''" : s;
}
